export function PxIcon({ name, size = 24, className = '', style, title }) {
  const i = IDX[name] ?? 0
  return (
    <span role={title ? 'img' : undefined} aria-label={title} aria-hidden={title ? undefined : true} title={title} className={`px-ic inline-block shrink-0 align-middle ${className}`}
      style={{ width: size, height: size, backgroundImage: `url(${URL})`, backgroundSize: `${COLS * size}px ${ROWS * size}px`, backgroundPosition: `-${(i % COLS) * size}px -${Math.floor(i / COLS) * size}px`, imageRendering: 'pixelated', ...style }} />
  )
}
const make = (name) => { const C = (p) => <PxIcon name={name} size={p.size} className={p.className} style={p.style} title={p['aria-label']} />; C.displayName = name; return C }

