/** an emoji spot that has pixel art: pass the art key (k); falls back to the emoji */
export const hasPx = (k) => k in IDX
export function Emo({ k, e, size = 22, className = '' }) {
  return k && k in IDX ? <PxIcon name={k} size={size} className={className} /> : <span className={className}>{e}</span>
}
